let taskIdCounter = 1

function t(day, week, title, description, priority = 'Medium', estimatedTime = '2 hrs', category = 'General') {
  const id = `task-${String(taskIdCounter++).padStart(3, '0')}`
  return {
    id,
    day,
    week,
    title,
    description,
    priority,
    estimatedTime,
    category,
    status: 'Not Started',
    completed: false,
    completedAt: null,
    notes: '',
    scheduledDate: '',
  }
}

